import sys
from math import isqrt

def main():
    MAX = 10**6 + 1

    omega = [0] * MAX
    for i in range(2, MAX):
        if omega[i] == 0:
            for j in range(i, MAX, i):
                omega[j] += 1

    best = [0] * MAX
    cur = 0
    for x in range(MAX):
        if omega[x] == 2:
            cur = x
        best[x] = cur

    data = sys.stdin.buffer.read().split()
    q = int(data[0])

    ans = []
    for i in range(1, q + 1):
        a = int(data[i])
        m = best[isqrt(a)]
        ans.append(str(m * m))

    print("\n".join(ans))

if __name__ == "__main__":
    main()
